INSERT INTO `blogs` VALUES (1,'Profil Mirai Akademi','概要：ミライアカデミー','hai','こんにちは','Mirai Akademi adalah tempat pelatihan kerja swasta yang berkomitmen untuk memberikan pelatihan berkualitas guna menghasilkan tenaga kerja unggul di Indonesia. Kami berfokus pada pengembangan kompetensi peserta agar siap bersaing dan sukses dalam dunia kerja di Jepang.\n\nMirai Akademi menyediakan program pelatihan komprehensif yang mencakup pembelajaran bahasa Jepang, budaya, serta keterampilan profesional(SSW). Dengan fasilitas yang lengkap dan instruktur berpengalaman, kami siap mendukung para peserta untuk meraih karir cemerlang di Jepang, serta membangun masa depan yang lebih baik.','ミライアカデミーは、インドネシアの優秀な人材を育成するために、質の高い研修を提供することを使命とする民間職業訓練機関です。\n私たちは、参加者の能力開発に焦点を当て、日本での就職において競争力を持ち、成功できるよう支援しています。\n\nミライアカデミーでは、日本語や日本文化、そして特定技能（SSW）に関する包括的な研修プログラムを提供しています。\n充実した施設と経験豊富な講師陣のもと、参加者が日本で輝かしいキャリアを築き、より良い未来を創るためのサポートを行っています',1,NULL,NULL,NULL,'https://apijob.miraiakademi.com/uploads/gambar/1753414125_6882f9edad8a9_acara-wisuda.jpeg','draft',NULL,NULL,NULL,NULL),(3,'Lulusan SMKTI Bali Global Klungkung Langsung Bekerja di Jepang','題名','lulusan-smkti-bali-global-klungkung-langsung-bekerja-di-jepang',NULL,'<p>Terobosan dan inovasi dalam dunia pendidikan Vokasi dilakukan oleh SMKTI Bali Global Klungkung dengan melakukan program wawancara kerja dengan lembaga penempatan kerja di jepang.</p>',NULL,1,NULL,'Admin',NULL,'https://apijob.miraiakademi.com/uploads/gambar/1753414125_6882f9edad8a9_acara-wisuda.jpeg','published',NULL,'2025-06-22 19:11:02','2025-08-05 11:54:13',NULL),(4,'Kenapa Harus Nunggu 2045 Kalau Kamu Bisa Mulai Sekarang di ITB STIKOM Bali?',NULL,'kenapa-harus-nunggu-2045-kalau-kamu-bisa-mulai-sekarang-di-itb-stikom-bali',NULL,'Pernah nggak sih kamu mikir, \'Nanti tahun 2045 aku bakal jadi apa ya?',NULL,1,NULL,'Admin',NULL,'https://apijob.miraiakademi.com/uploads/gambar/1753414125_6882f9edad8a9_acara-wisuda.jpeg','published',NULL,'2025-06-22 19:12:08','2025-06-22 19:12:08',NULL);
