INSERT INTO `sections` VALUES (42,'Section Hero Job',1,NULL,'section-hero-job',NULL,'<h1>Mammals Menyediakan Lowongan Kerja ke Jepang</h1><p>Temukan dan Daftar Sekarang! Sebagai mitra resmi dari Mirai Akademi, Mammals menyediakan sistem dan layanan job matching bagi calon pekerja dari Indonesia yang ingin bekerja di Jepang.</p><p>       </p>','<h1>Mammalsは日本での就職機会を提供します</h1><p>今すぐ探して応募しましょう！Mirai Akademiの公式パートナーとして、Mammalsは日本での就労を希望するインドネシア出身の求職者向けに、求人マッチングシステムとサービスを提供しています。</p>','active',NULL,'2025-07-29 17:52:56','2025-08-07 09:57:07',NULL),(46,'Section Hero Beranda',2,'ホームページ','section-hero-beranda',NULL,'\n\n\n\n\n\n    <div className=\"mb-40\">\n\n      <h2 className=\"text-xl md:text-2xl font-semibold text-gray-800\">\n\n       Peran <span className=\"bg-yellow-300 px-1 font-bold\">Mammals </span>\n\n       </h2>\n\n        <p className=\"text-md md:text-lg text-gray-700 mt-1\">Dalam Proses Rekrutmen  </p>\n\n        <div className=\"w-16 h-[2px] bg-black mx-auto mt-2\"> </div>\n\n      </div>\n\n\n     <div className=\"bg-white shadow-lg h-150 rounded-lg relative mt-10 z-0 border\" >\n\n      <div className=\"absolute -top-20 left-1/2 transform -translate-x-1/2 w-full max-w-6xl px-4 z-10\">\n\n       <div className=\"grid md:grid-cols-3 gap-6\">\n\n         <div\n\n          key=\"1\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaBriefcase className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           Menyediakan informasi lowongan pekerjaan dari perusahaan Jepang\n\n          </p>\n\n         </div>\n\n\n         <div\n\n          key=\"2\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaHandshake className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           Melakukan pencocokan antara kandidat dan perusahaan\n\n          </p>\n\n         </div>\n\n\n         <div\n\n          key=\"3\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaComments className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           Menjembatani proses wawancara dan komunikasi antar pihak\n\n          </p>\n\n        </div>\n\n       </div>\n </div>\n\n     </div>','<div className=\"mb-40\">\n\n      <h2 className=\"text-xl md:text-2xl font-semibold text-gray-800\">\n\n       役割 <span className=\"bg-yellow-300 px-1 font-bold\">Mammals</span>\n\n      </h2>\n\n      <p className=\"text-md md:text-lg text-gray-700 mt-1\">採用プロセスにおいて</p>\n\n      <div className=\"w-16 h-[2px] bg-black mx-auto mt-2\"></div>\n\n     </div>\n\n\n     <div className=\"bg-white shadow-lg h-150 rounded-lg relative mt-10 z-0 border\" >\n\n      <div className=\"absolute -top-20 left-1/2 transform -translate-x-1/2 w-full max-w-6xl px-4 z-10\">\n\n       <div className=\"grid md:grid-cols-3 gap-6\">\n\n         <div\n\n          key=\"1\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaBriefcase className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           日本企業の求人情報を提供\n\n          </p>\n\n         </div>\n\n\n         <div\n\n          key=\"2\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaHandshake className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           候補者と企業のマッチング\n\n          </p>\n\n         </div>\n\n\n         <div\n\n          key=\"3\"\n\n          className=\"bg-yellow-300 rounded-lg shadow-md p-6 flex flex-col items-center justify-center text-center\"\n\n         >\n\n          <div className=\"bg-white rounded-lg p-4 mb-4 flex items-center justify-center w-16 h-16\">\n\n           <FaComments className=\"text-3xl text-yellow-500\" />\n\n          </div>\n\n\n          <p className=\"text-sm md:text-base font-medium text-gray-800\">\n\n           面接プロセスと関係者間のコミュニケーションの橋渡し\n\n</p>\n\n         </div>\n\n       </div>\n\n      </div>\n\n     </div>','active',NULL,'2025-08-05 10:54:20','2025-08-05 10:54:20',NULL),(48,'Section Peran 1',5,'役割セクション','section-peran-1',NULL,'<p>Menyediakan informasi lowongan pekerjaan dari perusahaan Jepang</p><p>          </p>','<p>&lt;p className=\"text-sm md:text-base font-medium text-gray-800\"&gt;</p><p>日本企業の求人情報を提供します</p><p>&lt;/p&gt;</p>','active',NULL,'2025-08-06 13:15:56','2025-08-07 11:38:00',NULL),(49,'Section Peran 2',5,'役割セクション 2','section-peran-2',NULL,'<p>Melakukan pencocokan antara kandidat dan perusahaan</p><p><br></p><p><br></p><p>          </p>','<p>&lt;p className=\"text-sm md:text-base font-medium text-gray-800\"&gt;</p><p>候補者と企業のマッチング</p><p>&lt;/p&gt;</p>','active',NULL,'2025-08-06 13:16:53','2025-08-07 11:38:13',NULL),(50,'Section Peran 3',5,'役割セクション 3','section-peran-3',NULL,'<p>Menyediakan informasi lowongan pekerjaan dari perusahaan Jepang</p><p>          </p>','<p>&lt;p className=\"text-sm md:text-base font-medium text-gray-800\"&gt;</p><p>面接プロセスと関係者間のコミュニケーションの橋渡し</p><p>&lt;/p&gt;</p>','active',NULL,'2025-08-06 13:17:45','2025-08-07 11:38:22',NULL),(51,'Job Matching',6,'ジョブマッチング','job-matching',NULL,'<h1>Temukan Lowongan Kerja Ke Jepang</h1><h1>Sesuai Keahlianmu!</h1><p>Bersama Mammals, kamu dapat mengakses lowongan kerja dari perusahaan Jepang terpercaya.</p>','<h1>日本での求人情報を探す &lt;br className=\"hidden md:block\" /&gt;</h1><h1>あなたのスキルを活かせ！</h1><p>Mammalsなら、信頼できる日本企業の求人情報にアクセスできます。</p><p><br></p>','active',NULL,'2025-08-07 09:12:26','2025-08-07 09:59:17',NULL),(52,'beranda perusahaan',7,'会社のホームページ','beranda-perusahaan',NULL,'<h1>Kami Siap Mendukung Rekrutmen Perusahaan Anda</h1><p>Mammals sebagai mitra resmi dari Mirai Akademi memberikan akses untuk melihat daftar calon pekerja, atau mengunggah lowongan kerja agar dapat dijangkau oleh kandidat yang tepat.</p>','<h1>貴社の採用活動を全力でサポートいたします</h1><p><br></p><p>ミライアカデミーの公式パートナーとして、Mammalsは求職者の情報を閲覧したり、求人情報をアップロードしたりすることで、最適な候補者にリーチするためのアクセスを提供します。</p>','active',NULL,'2025-08-07 10:05:24','2025-08-07 10:15:15',NULL),(53,'Mengapa Memilih Mammals untuk Proses Perekrutan?',8,'採用プロセスに哺乳類を選ぶ理由','mengapa-memilih-mammals-untuk-proses-perekrutan',NULL,'<p>Layanan ini disediakan oleh Mammals secara gratis, tidak ada biaya untuk melihat daftar calon pekerja atau mengunggah lowongan kerja.</p><p><br></p><p>Mammals tidak hanya mempertemukan perusahaan Jepang dengan calon tenaga kerja dari Indonesia, tetapi juga mengelola seluruh proses rekrutmen secara terstruktur mulai dari menyediakan informasi lowongan pekerjaan, pencocokan kandidat hingga memfasilitasi komunikasi antara perusahaan dan calon pekerja.</p><p><br></p><p>Dengan sistem ini, perusahaan dapat menemukan kandidat yang tepat dan membangun kerja sama yang saling menguntungkan.</p>','<p>このサービスはMammalsによって無料で提供されており、候補者リストの閲覧や求人情報の掲載は無料です。</p><p><br></p><p>Mammalsは、日本企業とインドネシアの求職者を繋ぐだけでなく、求人情報の提供、候補者とのマッチング、企業と求職者間のコミュニケーション促進など、採用プロセス全体を体系的に管理します。</p><p><br></p><p>このシステムにより、企業は最適な候補者を見つけ、相互に有益なパートナーシップを構築することができます。</p>','active',NULL,'2025-08-07 10:37:45','2025-08-07 10:41:21',NULL),(54,'Lihat Daftar Pelamar',9,'応募者リストを見る','lihat-daftar-pelamar',NULL,'<h3>Lihat Daftar</h3><h3>Calon Pekerja</h3><h3>dari Mirai Akademi!</h3>','<h3>Mirai Academyの</h3><h3>就職希望者リストをご覧ください！</h3>','active',NULL,'2025-08-07 11:50:53','2025-08-07 11:58:34',NULL),(55,'Daftarkan Lowongan Anda',9,'求人情報を登録する','daftarkan-lowongan-anda',NULL,'<h3>Ingin membuka</h3><h3>kesempatan kerja</h3><h3>di perusahaan Anda?</h3>','<h3>貴社で</h3><h3>雇用機会を</h3><h3>創出したいとお考えですか？</h3>','active',NULL,'2025-08-07 12:01:51','2025-08-07 12:04:33',NULL),(56,'Section Calon Pelamar',10,'応募希望者セクション','section-calon-pelamar',NULL,'<h1>Temukan Calon Pekerja</h1><h1>Berkualitas Sesua</h1><h1>Bidang Keahlian</h1><p>Setiap calon pekerja disiapkan melalui tahapan seleksi, pelatihan, dan pendampingan untuk memastikan kesiapan kerja yang sesuai kebutuhan perusahaan.</p>','<h1>専門分野に応じて適格な候補者を見つけます</h1><p>各候補者は、選考プロセス、トレーニング、メンタリングを通じて、企業のニーズを満たす職務遂行能力を確実に備えます。</p>','active',NULL,'2025-08-07 12:28:43','2025-08-07 12:30:27',NULL),(57,'Daftar Pelamar Header',10,'応募者リストのヘッダー','daftar-pelamar-header',NULL,'<h1>Temukan Calon Pekerja</h1><h1>Berkualitas Sesuai</h1><h1>Bidang Keahlian</h1><p>Setiap calon pekerja disiapkan melalui tahapan seleksi, pelatihan, dan pendampingan untuk memastikan kesiapan kerja yang sesuai kebutuhan perusahaan.</p>','<h1>専門分野に応じて適格な候補者を見つけます</h1><p>各候補者は、選考プロセス、トレーニング、メンタリングを通じて、企業のニーズを満たす職務遂行能力を確実に備えます。</p>','active',NULL,'2025-08-07 14:37:53','2025-08-07 14:38:14',NULL),(58,'Step 1',12,'ステップ1','section-proses',NULL,'<p>Perusahaan dapat meninjau daftar kandidat dan memilih calon pekerja yang sesuai dengan kebutuhan.</p>','<p>企業は候補者リストを確認し、ニーズに合った求職者を選択できます。</p>','active',NULL,'2025-08-07 15:33:11','2025-08-07 15:33:11',NULL),(59,'Step 2',12,'ステップ2','section-proses',NULL,'<p>Setelah menemukan kandidat yang diminati, perusahaan mengisi formulir minat perekrutan.</p>','<p>興味のある候補者を見つけた後、企業は採用関心フォームに記入します。</p>','active',NULL,'2025-08-07 15:33:57','2025-08-07 15:33:57',NULL),(60,'Step 3',12,'ステップ3','section-proses',NULL,'<p>Tim kami akan segera menghubungi perusahaan untuk mengkonfirmasi ketertarikan dan menjelaskan langkah selanjutnya.</p>','<p>当社チームが近日中に企業に連絡し、関心の有無を確認し、次のステップについて説明します。</p>','active',NULL,'2025-08-07 15:34:44','2025-08-07 15:34:44',NULL),(61,'Step 4',12,'ステップ4','section-proses',NULL,'<p>Mammals akan membantu mengatur jadwal wawancara antara perusahaan dan kandidat.</p>','<p>哺乳類は企業と候補者の間の面接スケジュールの調整をお手伝いします。</p>','active',NULL,'2025-08-07 15:35:47','2025-08-07 15:35:47',NULL),(62,'Step 5',12,'ステップ5','section-proses',NULL,'<p>Setelah wawancara, perusahaan dapat membuat keputusan terkait perekrutan kandidat tersebut.</p>','<p>面接後、企業は候補者の採用に関して決定を下すことができます。</p>','active',NULL,'2025-08-07 15:36:24','2025-08-07 15:36:24',NULL);
